    using(var brush=new SolidBrush(selected?Gold:Bg))e.Graphics.FillRectangle(brush,row);
    Rectangle label=e.Node.Bounds;label.Y=row.Y;label.Height=row.Height;label.Width=Math.Max(0,tree.ClientSize.Width-label.X-6);
