   };
   tree.AfterSelect+=(s,e)=>tree.Invalidate();tree.GotFocus+=(s,e)=>tree.Invalidate();tree.LostFocus+=(s,e)=>tree.Invalidate();
   list.OwnerDraw=true;list.DrawColumnHeader+=(s,e)=>{using(var b=new SolidBrush(Panel))e.Graphics.FillRectangle(b,e.Bounds);TextRenderer.DrawText(e.Graphics,e.Header.Text,list.Font,e.Bounds,Muted,TextFormatFlags.Left|TextFormatFlags.VerticalCenter);};list.DrawItem+=(s,e)=>{};list.DrawSubItem+=(s,e)=>{using(var b=new SolidBrush(e.Item.Selected?Gold:Bg))e.Graphics.FillRectangle(b,e.Bounds);var r=e.Bounds;r.Inflate(-6,0);TextRenderer.DrawText(e.Graphics,e.SubItem.Text,list.Font,r,e.Item.Selected?Bg:Text,TextFormatFlags.Left|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis|TextFormatFlags.NoPrefix);};SetWindowTheme(tree.Handle,"","");SetWindowTheme(list.Handle,"DarkMode_Explorer",null);
  }
  public static Color Bg=Color.FromArgb(23,23,25),Panel=Color.FromArgb(32,32,34),Gold=Color.FromArgb(219,181,92),Text=Color.FromArgb(226,226,226),Muted=Color.FromArgb(155,155,155);
  public static void Apply(Control c){c.BackColor=Bg;c.ForeColor=Text;c.Font=new Font("Microsoft YaHei UI",10);foreach(Control child in c.Controls)Apply(child);var b=c as Button;if(b!=null){b.FlatStyle=FlatStyle.Flat;b.FlatAppearance.BorderColor=Color.FromArgb(73,69,58);b.BackColor=Panel;b.ForeColor=Gold;b.Cursor=Cursors.Hand;}var t=c as TextBox;if(t!=null){t.BackColor=Panel;t.BorderStyle=BorderStyle.FixedSingle;}var f=c as Form;if(f!=null){f.Icon=Icon.ExtractAssociatedIcon(Application.ExecutablePath);f.StartPosition=FormStartPosition.CenterScreen;Dark(f);}}
  public static Button Button(string text,Action action,int width){var b=new Button{Text=text,Width=width,Height=36,Margin=new Padding(4)};b.Click+=(s,e)=>action();return b;}
  public static void Error(Exception e){MessageBox.Show(e.Message,"Vaultline",MessageBoxButtons.OK,MessageBoxIcon.None);}
  public static string Ask(string title,string label,string initial,bool password){using(var f=new Form{Text=title,ClientSize=new Size(490,190),FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false}){var l=new Label{Text=label,Left=24,Top=22,Width=445,Height=44};var t=new TextBox{Text=initial,Left=24,Top= seventy(),Width=440,UseSystemPasswordChar=password};var ok=Button("确定",()=>f.DialogResult=DialogResult.OK,100);ok.Left=364;ok.Top=126;f.Controls.AddRange(new Control[]{l,t,ok});f.AcceptButton=ok;Theme.Apply(f);return f.ShowDialog()==DialogResult.OK?t.Text:null;}}
