   Controls.Add(new Label{Text=create?"为本地保险库设置主密码（至少 12 个字符）":"你的隐私，只存放在你的电脑。",Left=34,Top=88,Width=480,Height=30});
   pass=new TextBox{Left=34,Top=136,Width=480,UseSystemPasswordChar=true};Controls.Add(pass);
