   Controls.Add(new Label{Text="存储位置："+Path.GetDirectoryName(s.FilePath),Left=34,Top=378,Width=480,Height=42,AutoEllipsis=true});Theme.Apply(this);Controls[0].Font=new Font("Microsoft YaHei UI",23,FontStyle.Bold);Controls[0].ForeColor=Theme.Gold;
  }
  void Unlock(){try{if(create&&(pass.Text.Length<12||pass.Text!=confirm.Text))throw new Exception("主密码至少 12 个字符，且两次输入必须一致。");UseWaitCursor=true;store.Unlock(pass.Text);if(create)store.Save();pass.Clear();if(confirm!=null)confirm.Clear();DialogResult=DialogResult.OK;}catch(Exception e){status.Text=e.Message;}finally{UseWaitCursor=false;}}
