   json=new TextBox{Dock=DockStyle.Fill,Multiline=true,AcceptsReturn=true,AcceptsTab=true,ScrollBars=ScrollBars.Both,WordWrap=false,Text=entry==null?"{\r\n  \"微信号\": \"\",\r\n  \"password\": \"\",\r\n  \"绑定的手机号\": \"\",\r\n  \"绑定的银行卡\": \"\"\r\n}":Engine.Pretty(entry.Fields)};
   layout.Controls.Add(new Label{Text="完整路径 / 最后一段即唯一标签",AutoSize=true});layout.Controls.Add(path);layout.Controls.Add(new Label{Text="隐私级别（所有级别均加密）",AutoSize=true});layout.Controls.Add(level);layout.Controls.Add(new Label{Text="账号内容 · JSON 对象（编辑时可见明文）",AutoSize=true});layout.Controls.Add(json);layout.Controls.Add(new Label{Text="路径示例 account/wechat/work-account · 字段可使用中文或英文",AutoSize=true});
   var buttons=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.RightToLeft};buttons.Controls.Add(Theme.Button("保存",Save,100));buttons.Controls.Add(Theme.Button("取消",()=>Close(),90));buttons.Controls.Add(Theme.Button("格式化",()=>{try{json.Text=Engine.Pretty(Parse());}catch(Exception e){Theme.Error(e);}},95));layout.Controls.Add(buttons);Controls.Add(layout);Theme.Apply(this);json.Font=new Font("Consolas",11);
  }
  Dictionary<string,object> Parse(){var d=Engine.Json.DeserializeObject(json.Text) as Dictionary<string,object>;if(d==null)throw new Exception("请输入有效的 JSON 对象，例如 {\"password\":\"...\"}。");return d;}
  void Save(){try{string p=Engine.Normalize(path.Text);Engine.ValidatePath(p);Result=new Entry{Path=p,Fields=Parse(),Level=level.Text,Updated=DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")};DialogResult=DialogResult.OK;}catch(Exception e){Theme.Error(e);}}
 }
 public class Activity:IMessageFilter {public DateTime Last=DateTime.UtcNow;public bool PreFilterMessage(ref Message m){if(m.Msg==0x100||m.Msg==0x201||m.Msg==0x204||m.Msg==0x20A||m.Msg==0x200)Last=DateTime.UtcNow;return false;}}
 public class MainForm:Form {
  Store store;TreeView tree;ListView list;TextBox search,detail;Label heading,meta,status;Button reveal;Entry selected;object selectedValue;bool shown,locking,loading;string folder="",selectedFolder;DateTime showUntil;Timer timer=new Timer{Interval=1000};Activity activity=new Activity();
  public MainForm(Store s){store=s;Text="Vaultline · 离线隐私管理";ClientSize=new Size(1280,800);MinimumSize=new Size(1050,680);
   var root=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=5,ColumnCount=1,Padding=new Padding(22)};root.RowStyles.Add(new RowStyle(SizeType.Absolute,70));root.RowStyles.Add(new RowStyle(SizeType.Absolute,55));root.RowStyles.Add(new RowStyle(SizeType.AutoSize));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.Absolute,36));
   var top=new Panel{Dock=DockStyle.Fill};var title=new Label{Text="Vaultline",Left=0,Top=0,Width=205,Height=45};var subtitle=new Label{Text="本地隐私保险库",Left=220,Top=17,Width=420,Height=30};var secure=new Label{Text="●  离线存储   /   已加密",Dock=DockStyle.Right,Width=215,TextAlign=ContentAlignment.MiddleRight};top.Controls.AddRange(new Control[]{title,subtitle,secure});root.Controls.Add(top);
   var searchPanel=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2};searchPanel.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));searchPanel.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,106));search=new TextBox{Dock=DockStyle.Fill,Margin=new Padding(0,7,10,0)};search.KeyDown+=(o,e)=>{if(e.KeyCode==Keys.Enter){Search();e.SuppressKeyPress=true;}};searchPanel.Controls.Add(search);searchPanel.Controls.Add(Theme.Button("搜索 / 跳转",Search,100));root.Controls.Add(searchPanel);
   var bar=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=true,AutoSize=true,AutoSizeMode=AutoSizeMode.GrowAndShrink};bar.Controls.Add(Theme.Button("＋ 分组",NewFolder,95));bar.Controls.Add(Theme.Button("＋ 账号",()=>Edit(true),95));bar.Controls.Add(Theme.Button("编辑 / 移动",()=>Edit(false),110));bar.Controls.Add(Theme.Button("删除",Delete,72));bar.Controls.Add(Theme.Button("加密备份",Backup,95));bar.Controls.Add(Theme.Button("恢复备份",Restore,95));bar.Controls.Add(Theme.Button("主密码",Password,80));bar.Controls.Add(Theme.Button("锁定",Lock,72));bar.Controls.Add(Theme.Button("导出数据",ExportAll,90));bar.Controls.Add(Theme.Button("一键导入",ImportAll,90));bar.Controls.Add(Theme.Button("帮助",Help,70));root.Controls.Add(bar);
   var panes=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=3,RowCount=1};panes.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,240));panes.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,48));panes.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,52));
   tree=new TreeView{Dock=DockStyle.Fill,BorderStyle=BorderStyle.None,HideSelection=false,FullRowSelect=true,ItemHeight=32,ShowLines=false};tree.AfterSelect+=(o,e)=>{if(loading)return;folder=(string)e.Node.Tag;search.Clear();RefreshList(null);};panes.Controls.Add(tree);
   list=new ListView{Dock=DockStyle.Fill,View=View.Details,FullRowSelect=true,HideSelection=false,MultiSelect=false,BorderStyle=BorderStyle.None};list.Columns.Add("标签 / 名称",190);list.Columns.Add("隐私级别",80);list.Columns.Add("所在目录",260);list.SelectedIndexChanged+=(o,e)=>{if(list.SelectedItems.Count>0){var item=list.SelectedItems[0];if(item.Tag is Entry)Select((Entry)item.Tag,null,false);else {ClearDetail();selectedFolder=(string)item.Tag;}}};list.DoubleClick+=(o,e)=>{if(list.SelectedItems.Count>0&&list.SelectedItems[0].Tag is string)Navigate((string)list.SelectedItems[0].Tag);};panes.Controls.Add(list);
