   Theme.Apply(this);title.Font=new Font("Microsoft YaHei UI",25,FontStyle.Bold);title.ForeColor=secure.ForeColor=Theme.Gold;heading.Font=new Font("Microsoft YaHei UI",15,FontStyle.Bold);detail.Font=new Font("Consolas",11);tree.LineColor=Theme.Muted;Theme.Explorer(tree,list);Theme.Hint(search,"输入目录 / 标签 / 字段，例如 account/wechat/work-account/password");Application.AddMessageFilter(activity);timer.Tick+=Tick;timer.Start();SystemEvents.SessionSwitch+=SessionSwitch;FormClosed+=(o,e)=>{timer.Stop();timer.Dispose();SystemEvents.SessionSwitch-=SessionSwitch;Application.RemoveMessageFilter(activity);store.Dispose();};KeyPreview=true;KeyDown+=(o,e)=>{if(e.Control&&e.KeyCode==Keys.L){Lock();e.SuppressKeyPress=true;}if(e.Control&&e.KeyCode==Keys.F){search.Focus();search.SelectAll();e.SuppressKeyPress=true;}};Rebuild();
  }
  void SessionSwitch(object s,SessionSwitchEventArgs e){if(e.Reason==SessionSwitchReason.SessionLock&&IsHandleCreated)BeginInvoke(new Action(Lock));}
  void Tick(object s,EventArgs e){if(shown&&DateTime.UtcNow>=showUntil){shown=false;Render();}if(!locking&&DateTime.UtcNow-activity.Last>TimeSpan.FromMinutes(5))Lock();}
  void ClearDetail(){selectedFolder=null;selected=null;selectedValue=null;shown=false;heading.Text="账号详情";meta.Text="选择一个账号，或输入完整路径定位字段。";detail.Text="\r\n  隐私信息默认隐藏\r\n\r\n  路径示例：\r\n  account/wechat/work-account/password";reveal.Text="显示 30 秒";}
  void Select(Entry e,object value,bool isField){selected=e;selectedValue=isField?value:e.Fields;shown=false;heading.Text=Engine.Name(e.Path);meta.Text=e.Path+"\r\n"+e.Level+"  ·  "+e.Updated;Render();}
  void Render(){reveal.Text=shown?"隐藏内容":"显示 30 秒";if(selected==null)return;if(shown)detail.Text=Engine.DisplayLines(selectedValue);else{var d=selectedValue as Dictionary<string,object>;detail.Text=d==null?"••••••••":string.Join("\r\n\r\n",d.Keys.Select(k=>k+"  :  ••••••••"));}}
  void Reveal(){if(selected==null)return;shown=!shown;showUntil=DateTime.UtcNow.AddSeconds(30);Render();}
  void Copy(){if(selected==null)return;try{string text=Engine.CopyLines(selectedValue);if(text.Length==0){status.Text="当前内容为空，没有可复制的值。";return;}Clipboard.SetText(text);status.Text="已复制内容";}catch(Exception e){Theme.Error(e);}}
  void ExportAll(){
   if(locking||store.Value==null)return;
   using(var dialog=new SaveFileDialog{Title="导出全部数据",Filter="JSON 数据文件|*.json",DefaultExt="json",AddExtension=true,OverwritePrompt=true,FileName="Vaultline-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".json"}){
    if(dialog.ShowDialog(this)!=DialogResult.OK||locking||store.Value==null)return;
    try{Engine.WriteExport(dialog.FileName,Engine.ExportAll(store.Value),store.FilePath);status.Text="已导出 "+store.Value.Entries.Count+" 个账号："+dialog.FileName;}catch(Exception e){Theme.Error(e);}
   }
  }
  void ImportAll(){
   if(locking||store.Value==null)return;
   using(var dialog=new OpenFileDialog{Title="一键导入",Filter="Vaultline 导出文件|*.json",Multiselect=false}){
    if(dialog.ShowDialog(this)!=DialogResult.OK||locking||store.Value==null)return;
    Vault previous=store.Value;
    try{
     if(new FileInfo(dialog.FileName).Length>32000000)throw new Exception("导入文件过大，最多支持 32 MB。");
     var incoming=Engine.ParseImport(File.ReadAllText(dialog.FileName));var result=Engine.MergeImport(previous,incoming);
     store.Value=result.Value;store.Save();Rebuild();status.Text="已导入 "+result.Added+" 个账号，跳过 "+result.Skipped+" 个重复账号，重命名 "+result.Renamed+" 个冲突账号";
    }catch(Exception e){store.Value=previous;Rebuild();Theme.Error(e);}
   }
  }
  void Rebuild(){loading=true;tree.Nodes.Clear();var root=new TreeNode("保险库"){Tag=""};tree.Nodes.Add(root);var map=new Dictionary<string,TreeNode>(StringComparer.OrdinalIgnoreCase);map[""]=root;foreach(string p in store.Value.Folders.OrderBy(x=>x.Count(c=>c=='/')).ThenBy(x=>x)){var n=new TreeNode(Engine.Name(p)){Tag=p};map[Engine.Parent(p)].Nodes.Add(n);map[p]=n;}root.Expand();if(!map.ContainsKey(folder))folder="";tree.SelectedNode=map[folder];tree.SelectedNode.EnsureVisible();loading=false;RefreshList(null);}
  void Navigate(string p){folder=p;Rebuild();}
  void RefreshList(IEnumerable<Entry> results){list.Items.Clear();ClearDetail();if(results==null){foreach(string f in store.Value.Folders.Where(f=>Engine.Equal(Engine.Parent(f),folder)).OrderBy(x=>x)){var item=new ListViewItem("▸  "+Engine.Name(f)){Tag=f};item.SubItems.Add("分组");item.SubItems.Add(f);list.Items.Add(item);}results=store.Value.Entries.Where(x=>Engine.Equal(Engine.Parent(x.Path),folder));}foreach(var e in results.OrderBy(x=>x.Path)){var item=new ListViewItem(Engine.Name(e.Path)){Tag=e};item.SubItems.Add(e.Level);item.SubItems.Add(Engine.Parent(e.Path));list.Items.Add(item);}status.Text="位置："+(folder==""?"保险库":folder)+"   ·   "+store.Value.Entries.Count+" 个账号   ·   "+Path.GetDirectoryName(store.FilePath);}
  void Search(){try{string q=Engine.Normalize(search.Text);if(q==""){RefreshList(null);return;}string f=store.Value.Folders.FirstOrDefault(x=>Engine.Equal(x,q));if(f!=null){Navigate(f);return;}Entry e;object value=Engine.Resolve(store.Value,q,out e);if(e!=null){RefreshList(new[]{e});Select(e,value,!Engine.Equal(e.Path,q));status.Text="已定位："+q+"   ·   点击显示或复制内容";return;}RefreshList(store.Value.Entries.Where(x=>x.Path.IndexOf(q,StringComparison.OrdinalIgnoreCase)>=0));status.Text="找到 "+list.Items.Count+" 个账号（仅搜索目录和标签，不扫描秘密字段）。";}catch(Exception e){ClearDetail();Theme.Error(e);}}
  void Mutate(Action action){string before=Engine.Json.Serialize(store.Value);try{action();store.Save();Rebuild();}catch(Exception e){store.Value=Engine.Json.Deserialize<Vault>(before);Rebuild();Theme.Error(e);}}
  void NewFolder(){string name=Theme.Ask("新建分组","输入完整目录路径，例如 account/wechat",folder==""?"":folder+"/",false);if(name!=null)Mutate(()=>Engine.AddFolder(store.Value,Engine.Normalize(name)));}
  void Edit(bool create){string activeFolder=selectedFolder??folder;if(!create&&selected==null){if(activeFolder=="")return;string name=Theme.Ask("重命名 / 移动分组","输入新的完整路径",activeFolder,false);if(name==null)return;string target=Engine.Normalize(name),source=activeFolder;Mutate(()=>{Engine.ValidatePath(target);if(Engine.Equal(source,target))return;if(Engine.Under(target,source))throw new Exception("不能把目录移动到自己的子目录。");var affected=store.Value.Folders.Where(x=>Engine.Under(x,source)).ToList();var records=store.Value.Entries.Where(x=>Engine.Under(x.Path,source)).ToList();if(store.Value.Folders.Any(x=>!affected.Contains(x)&&Engine.Equal(x,target))||store.Value.Entries.Any(x=>Engine.Equal(x.Path,target)))throw new Exception("目标路径已存在。");store.Value.Folders.RemoveAll(x=>affected.Contains(x));foreach(string x in affected)Engine.AddFolder(store.Value,target+x.Substring(source.Length));foreach(Entry x in records)x.Path=target+x.Path.Substring(source.Length);folder=target;});return;}Entry old=create?null:selected;using(var f=new Editor(activeFolder,old)){if(f.ShowDialog(this)==DialogResult.OK)Mutate(()=>Engine.Put(store.Value,f.Result,old));}}
  void Delete(){if(selected!=null){Entry e=selected;if(MessageBox.Show("删除账号 “"+Engine.Name(e.Path)+"”？","Vaultline",MessageBoxButtons.YesNo,MessageBoxIcon.None)==DialogResult.Yes)Mutate(()=>store.Value.Entries.Remove(e));}else if((selectedFolder??folder)!=""){string f=selectedFolder??folder;int count=store.Value.Entries.Count(x=>Engine.Under(x.Path,f));if(MessageBox.Show("删除分组 “"+f+"” 及其全部子目录和 "+count+" 个账号？","Vaultline",MessageBoxButtons.YesNo,MessageBoxIcon.None)==DialogResult.Yes)Mutate(()=>{store.Value.Entries.RemoveAll(x=>Engine.Under(x.Path,f));store.Value.Folders.RemoveAll(x=>Engine.Under(x,f));folder=Engine.Parent(f);});}}
  void Backup(){using(var d=new SaveFileDialog{Filter="Vaultline加密备份|*.jx",FileName="Vaultline备份-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".jx"})if(d.ShowDialog()==DialogResult.OK){try{if(Path.GetFullPath(d.FileName).Equals(Path.GetFullPath(store.FilePath),StringComparison.OrdinalIgnoreCase))throw new Exception("请选择保险库以外的备份文件。");File.Copy(store.FilePath,d.FileName,true);status.Text="加密备份已保存："+d.FileName;}catch(Exception e){Theme.Error(e);}}}
  void Restore(){using(var d=new OpenFileDialog{Filter="Vaultline加密文件|*.jx;*.bak"})if(d.ShowDialog()==DialogResult.OK){string p=Theme.Ask("恢复备份","输入该备份创建时的主密码","",true);if(p==null)return;byte[] k=null,plain=null;try{byte[] b=File.ReadAllBytes(d.FileName);k=Crypto.Derive(p,Crypto.Salt(b));plain=Crypto.Open(b,k);Vault v=Engine.Json.Deserialize<Vault>(System.Text.Encoding.UTF8.GetString(plain));Engine.Validate(v);if(MessageBox.Show("备份含 "+v.Entries.Count+" 个账号，将替换当前保险库。继续？\r\n替换前会保存一份自动备份。","恢复备份",MessageBoxButtons.YesNo,MessageBoxIcon.None)==DialogResult.Yes){File.Copy(store.FilePath,store.FilePath+".before-restore-"+DateTime.Now.ToString("yyyyMMddHHmmss"),false);Mutate(()=>store.Value=v);}}catch(Exception e){Theme.Error(e);}finally{if(k!=null)Array.Clear(k,0,k.Length);if(plain!=null)Array.Clear(plain,0,plain.Length);}}}
  void Password(){string p=Theme.Ask("更改主密码","输入新主密码（至少 12 个字符）","",true);if(p==null)return;if(p.Length<12){Theme.Error(new Exception("主密码至少 12 个字符。"));return;}string c=Theme.Ask("确认主密码","再次输入新主密码","",true);if(c==null)return;if(p!=c){Theme.Error(new Exception("两次输入不一致。"));return;}try{store.ChangePassword(p);MessageBox.Show("主密码已更新。历史备份仍需使用备份时的密码。","Vaultline");}catch(Exception e){Theme.Error(e);}}
  void Lock(){if(locking)return;locking=true;foreach(Form f in Application.OpenForms.Cast<Form>().Where(f=>f!=this).ToArray()){f.DialogResult=DialogResult.Cancel;f.Close();}ClearDetail();list.Items.Clear();tree.Nodes.Clear();search.Clear();store.Lock();Hide();using(var f=new UnlockForm(store)){if(f.ShowDialog()==DialogResult.OK){activity.Last=DateTime.UtcNow;Rebuild();Show();Activate();locking=false;}else Close();}}
  void Help(){MessageBox.Show("目录：新建分组，支持多级路径；双击分组进入。\r\n账号：一个标签对应一个 JSON 对象；编辑完整路径即可移动。\r\n搜索：account/wechat/work-account\r\n字段：account/wechat/work-account/password\r\n嵌套字段：.../bank/card；数组：.../cards/0\r\n字段名中的 / 写为 ~1，~ 写为 ~0；字段名区分大小写。\r\n隐私分级：普通 / 敏感 / 机密，全部加密且默认隐藏。\r\nCtrl+F 搜索；Ctrl+L 锁定。闲置 5 分钟或系统锁屏自动锁定。\r\n编辑窗闲置锁定会丢弃尚未保存的内容。\r\n复制内容按行输出字段值；定位单个字段时可直接复制登录。\r\n导出数据会保存全部分组和账号；一键导入支持其他设备的导出文件，冲突项保留双方。\r\n请定期备份。主密码遗失无法恢复；系统剪贴板历史可能保留复制内容。\r\n\r\n存储："+store.FilePath,"Vaultline · 使用说明");}
 }
 public static class Program {
  [STAThread] public static void Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);if(args.Contains("--self-test")){SelfTest.Run();return;}if(args.Contains("--preview")){try{Preview.Run();}catch(Exception error){File.WriteAllText(Path.GetFullPath(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"..","tests","ui-results.txt")),error.ToString());Environment.ExitCode=1;}return;}try{string dir=StoragePaths.ResolveData(AppDomain.CurrentDomain.BaseDirectory);var store=new Store(dir);using(var unlock=new UnlockForm(store)){if(unlock.ShowDialog()!=DialogResult.OK){store.Dispose();return;}}Application.Run(new MainForm(store));}catch(Exception e){Theme.Error(new Exception("无法打开Vaultline："+e.Message+"\r\n若已打开另一个Vaultline窗口，请先关闭它。"));}}
 }
}
